begin;
with j as (select * from jsonb_to_recordset($law7d0001$[{"code_id":"APK_RF","article_number":"1","version_date":"2002-07-24","article_text":"Правосудие в сфере предпринимательской и иной экономической деятельности осуществляется арбитражными судами в Российской Федерации, образованными в соответствии с Конституцией Российской Федерации и федеральным конституционным законом (далее - арбитражные суды), путем разрешения экономических споров и рассмотрения иных дел, отнесенных к их компетенции Арбитражным процессуальным кодексом Российской Федерации и другими федеральными законами, по правилам, установленным законодательством о судопроизводстве в арбитражных судах.","article_title":"Статья 1. Осуществление правосудия арбитражными судами","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"51f0a54fc0f49a7f24159a26a4c89d0487254c3cc2c945c3a49327bbbbe79a66"},{"code_id":"APK_RF","article_number":"10","version_date":"2002-07-24","article_text":"1. Арбитражный суд при разбирательстве дела обязан непосредственно исследовать все доказательства по делу.\n\n2. Доказательства, которые не были предметом исследования в судебном заседании, не могут быть положены арбитражным судом в основу принимаемого судебного акта.","article_title":"Статья 10. Непосредственность судебного разбирательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0d29a78eed47d3a8d898c7409ec3ff647c1d0f4b2d7964e0edbf372e814d49b1"},{"code_id":"APK_RF","article_number":"100","version_date":"2002-07-24","article_text":"Правила об обеспечении иска, предусмотренные настоящей главой, применяются при обеспечении исполнения судебных актов.","article_title":"Статья 100. Обеспечение исполнения судебных актов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"64d7dd83a116270c6d052264a70746537bec2d6bc8d6d096f2cf1ed282422611"},{"code_id":"APK_RF","article_number":"101","version_date":"2002-07-24","article_text":"Судебные расходы состоят из государственной пошлины и судебных издержек, связанных с рассмотрением дела арбитражным судом.","article_title":"Статья 101. Состав судебных расходов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8c6a156c79ca5e0ffca1d3aad14672e2b1d24fc9d7f64d7e4b5d318fffc546e8"},{"code_id":"APK_RF","article_number":"102","version_date":"2002-07-24","article_text":"Основания и порядок уплаты государственной пошлины, а также порядок предоставления отсрочки или рассрочки уплаты государственной пошлины устанавливаются в соответствии с законодательством Российской Федерации о налогах и сборах.\n\n(Статья в редакции Федерального закона от 02.11.2004 № 127-ФЗ)","article_title":"Статья 102. Уплата государственной пошлины","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a15ef147f7654f4df0e8d2ce9fc45827758105698d55dbd88291d073a9b0a441"},{"code_id":"APK_RF","article_number":"103","version_date":"2002-07-24","article_text":"1. Цена иска определяется:\n\n1) по искам о взыскании денежных средств, исходя из взыскиваемой суммы;\n\n2) по искам о признании не подлежащим исполнению исполнительного или иного документа, по которому взыскание производится в бесспорном (безакцептном) порядке, исходя из оспариваемой денежной суммы;\n\n3) по искам об истребовании имущества, исходя из стоимости истребуемого имущества;\n\n4) по искам об истребовании земельного участка, исходя из стоимости земельного участка.\n\nВ цену иска включаются также указанные в исковом заявлении суммы неустойки (штраф, пени) и проценты.\n\nЦена иска, состоящего из нескольких самостоятельных требований, определяется суммой всех требований.\n\n2. По исковым заявлениям о признании права, в том числе права собственности, права пользования, права владения, права распоряжения, государственная пошлина уплачивается в размерах, установленных для исковых заявлений неимущественного характера.\n\n3. Цена иска указывается заявителем.\n\nВ случае неправильного указания заявителем цены иска она определяется арбитражным судом.","article_title":"Статья 103. Цена иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a69ed8e4908838a31c50e939e0d25663c6baea7801cb6dabd6efe80786e61d8c"},{"code_id":"APK_RF","article_number":"104","version_date":"2002-07-24","article_text":"Основания и порядок возврата или зачета государственной пошлины устанавливаются в соответствии с законодательством Российской Федерации о налогах и сборах.\n\n(Статья в редакции Федерального закона от 02.11.2004 № 127-ФЗ)","article_title":"Статья 104. Основания и порядок возврата или зачета государственной пошлины","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4113e91650ed5086d3929256e70ae44b3755d79f380baee367695ce87507e24b"},{"code_id":"APK_RF","article_number":"105","version_date":"2002-07-24","article_text":"Льготы по уплате государственной пошлины предоставляются в случаях и порядке, которые установлены законодательством Российской Федерации о налогах и сборах.\n\n(Статья в редакции Федерального закона от 02.11.2004 № 127-ФЗ)","article_title":"Статья 105. Льготы по уплате государственной пошлины","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"291bf3860364f284ea68d36cf2715a0b6a281f87af835054b9c358f9c381e2bb"},{"code_id":"APK_RF","article_number":"106","version_date":"2002-07-24","article_text":"К судебным издержкам, связанным с рассмотрением дела в арбитражном суде, относятся денежные суммы, подлежащие выплате экспертам, специалистам, свидетелям, переводчикам, расходы, связанные с проведением осмотра доказательств на месте, расходы на оплату услуг адвокатов и иных лиц, оказывающих юридическую помощь (представителей), расходы юридического лица на уведомление о корпоративном споре в случае, если федеральным законом предусмотрена обязанность такого уведомления, и другие расходы, понесенные лицами, участвующими в деле, в связи с рассмотрением дела в арбитражном суде. (В редакции федеральных законов от 19.07.2009 № 205-ФЗ; от 08.12.2011 № 422-ФЗ)","article_title":"Статья 106. Судебные издержки","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d73b938dd7fda1208c11736b7bbdc8c50ab7f05fe2ce083a67d09352a9bf20cc"},{"code_id":"APK_RF","article_number":"107","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\nРазмер вознаграждения эксперту определяется судом по согласованию с лицами, участвующими в деле, и по соглашению с экспертом.\n\nРазмер вознаграждения переводчику определяется судом по соглашению с переводчиком.","article_title":"Статья 107. Денежные суммы, подлежащие выплате экспертам, специалистам, свидетелям и переводчикам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"007ec7a2ac7502269f5c9346e7ad984ca9a63defe1884a9a46046880d9a4b734"},{"code_id":"APK_RF","article_number":"108","version_date":"2002-07-24","article_text":"1. Денежные суммы, подлежащие выплате экспертам и свидетелям, вносятся на депозитный счет арбитражного суда лицом, заявившим соответствующее ходатайство, в срок, установленный арбитражным судом. Если указанное ходатайство заявлено обеими сторонами, требуемые денежные суммы вносятся сторонами на депозитный счет арбитражного суда в равных частях.\n\n2. В случае, если в установленный арбитражным судом срок на депозитный счет арбитражного суда не были внесены денежные суммы, подлежащие выплате экспертам и свидетелям, арбитражный суд вправе отклонить ходатайство о назначении экспертизы и вызове свидетелей, если дело может быть рассмотрено и решение принято на основании других представленных сторонами доказательств.","article_title":"Статья 108. Внесение сторонами денежных сумм, необходимых для оплаты судебных издержек","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f7d485099b4f3ff0fb31680e757a674e76f8b9621a2f1ec66b7d8b12d1031d5"},{"code_id":"APK_RF","article_number":"109","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\nоплате услуг переводчика за счет средств федерального бюджета не распространяется на возмещение расходов на оплату услуг переводчика, понесенных иностранными лицами и лицами без гражданства, если иное не предусмотрено международным договором Российской Федерации.","article_title":"Статья 109. Выплата денежных сумм, причитающихся экспертам, специалистам, свидетелям и переводчикам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4dfc7e582d9157f46379f4d58899ce154a6778146ca9fc6f1b8c8ad5d12b7e6"},{"code_id":"APK_RF","article_number":"11","version_date":"2002-07-24","article_text":"1. Разбирательство дел в арбитражных судах открытое.\n\n2. Разбирательство дела в закрытом судебном заседании допускается в случаях, если открытое разбирательство дела может привести к разглашению государственной тайны, в иных случаях, предусмотренных федеральным законом, а также при удовлетворении ходатайства лица, участвующего в деле и\n\nссылающегося на необходимость сохранения коммерческой, служебной или иной охраняемой законом тайны.\n\n3. Разглашение сведений, составляющих государственную, коммерческую, служебную или иную охраняемую законом тайну, влечет за собой ответственность, установленную федеральным законом.\n\n4. О разбирательстве дела в закрытом судебном заседании выносится определение. Определение выносится в отношении всего судебного разбирательства или его части.","article_title":"Статья 11. Гласность судебного разбирательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"81d6045d93589a3c4f6bed9aa9bf3de20dd4ab198223d69025ee300d7ddba6bc"},{"code_id":"APK_RF","article_number":"110","version_date":"2002-07-24","article_text":"1. Судебные расходы, понесенные лицами, участвующими в деле, в пользу которых принят судебный акт, взыскиваются арбитражным судом со стороны.\n\nВ случае, если иск удовлетворен частично, судебные расходы относятся на лиц, участвующих в деле, пропорционально размеру удовлетворенных исковых требований.\n\n2. Расходы на оплату услуг представителя, понесенные лицом, в пользу которого принят судебный акт, взыскиваются арбитражным судом с другого лица, участвующего в деле, в разумных пределах.\n\n3. Государственная пошлина, от уплаты которой в установленном порядке истец был освобожден, взыскивается с ответчика в доход федерального бюджета пропорционально размеру удовлетворенных исковых требований, если ответчик не освобожден от уплаты государственной пошлины.\n\n4. При соглашении лиц, участвующих в деле, о распределении судебных расходов арбитражный суд относит на них судебные расходы в соответствии с этим соглашением.\n\n5. Судебные расходы, понесенные лицами, участвующими в деле, в связи с рассмотрением апелляционной, кассационной жалобы, распределяются по правилам, установленным настоящей статьей.","article_title":"Статья 110. Распределение судебных расходов между лицами, участвующими в деле","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"990e7f57fda0196c1a167b855fb5165a9a88aa415aa94fa4278ab20a01b5d624"},{"code_id":"APK_RF","article_number":"111","version_date":"2002-07-24","article_text":"1. В случае, если спор возник вследствие нарушения лицом, участвующим в деле, претензионного или иного досудебного порядка урегулирования спора, предусмотренного федеральным законом или договором, в том числе нарушения срока представления ответа на претензию, оставления претензии без ответа, арбитражный суд относит на это лицо судебные расходы независимо от результатов рассмотрения дела.\n\n2. Арбитражный суд вправе отнести все судебные расходы по делу на лицо, злоупотребляющее своими процессуальными правами или не выполняющее своих процессуальных обязанностей, если это привело к срыву судебного заседания, затягиванию судебного процесса, воспрепятствованию рассмотрения дела и принятию законного и обоснованного судебного акта.\n\n3. По заявлению лица, участвующего в деле, на которое возлагается возмещение судебных расходов, арбитражный суд вправе уменьшить размер возмещения, если этим лицом представлены доказательства их чрезмерности.","article_title":"Статья 111. Отнесение судебных расходов на лицо, злоупотребляющее своими процессуальными правами","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"34a877c696463f985b1f3558768c9f002a669ac860dac9bcb5527be7cd2ffcc4"},{"code_id":"APK_RF","article_number":"112","version_date":"2002-07-24","article_text":"1. Вопросы распределения судебных расходов, отнесения судебных расходов на лицо, злоупотребляющее своими процессуальными правами, и другие вопросы о судебных расходах разрешаются арбитражным судом соответствующей судебной инстанции в судебном акте, которым заканчивается рассмотрение дела по существу, или в определении.\n\nПропущенный по уважительной причине срок подачи такого заявления может быть восстановлен судом.\n\nЗаявление по вопросу о судебных расходах рассматривается по правилам, предусмотренным статьей 159 настоящего Кодекса, с учетом особенностей, установленных главой 29 настоящего Кодекса. (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\nПо результатам рассмотрения такого заявления выносится определение, которое может быть обжаловано.\n\n(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 112. Разрешение вопросов о судебных расходах","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ed13fe069301da877ad44a6bae1483849a192a435b82bb1e2b85de69f0c96caa"},{"code_id":"APK_RF","article_number":"113","version_date":"2002-07-24","article_text":"1. Процессуальные действия совершаются в сроки, установленные настоящим Кодексом или иными федеральными законами, а в случаях, если процессуальные сроки не установлены, они назначаются арбитражным судом.\n\n2. Сроки совершения процессуальных действий определяются точной календарной датой, указанием на событие, которое обязательно должно наступить, или периодом, в течение которого действие может быть совершено.\n\n3. Процессуальные сроки исчисляются годами, месяцами и днями. В сроки, исчисляемые днями, не включаются нерабочие дни.\n\n4. Течение процессуального срока, исчисляемого годами, месяцами или днями, начинается на следующий день после календарной даты или дня наступления события, которыми определено начало процессуального срока.","article_title":"Статья 113. Установление и исчисление процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1c8d3b6c4f3512427e3ab7b364731ca6af5586b12233cfe8694c83d42d714ade"},{"code_id":"APK_RF","article_number":"114","version_date":"2002-07-24","article_text":"1. Процессуальный срок, исчисляемый годами, истекает в соответствующий месяц и число последнего года установленного срока.\n\n2. Процессуальный срок, исчисляемый месяцами, истекает в соответствующее число последнего месяца установленного срока. Если окончание процессуального срока, исчисляемого месяцами, приходится на месяц, который соответствующего числа не имеет, срок истекает в последний день этого месяца.\n\n3. Процессуальный срок, исчисляемый днями, истекает в последний день установленного срока.\n\n4. В случаях, если последний день процессуального срока приходится на нерабочий день, днем окончания срока считается первый следующий за ним рабочий день.\n\n5. Процессуальное действие, для совершения которого установлен срок, может быть выполнено до двадцати четырех часов последнего дня установленного срока.\n\n6. Если заявление, жалоба, другие документы либо денежные суммы были сданы на почту, переданы или заявлены в орган либо уполномоченному их принять лицу до двадцати четырех часов последнего дня процессуального срока, срок не считается пропущенным.\n\n7. Если процессуальное действие должно быть совершено непосредственно в арбитражном суде или другой организации, срок истекает в тот час, когда в этом суде или этой организации по установленным правилам заканчивается рабочий день или прекращаются соответствующие операции.","article_title":"Статья 114. Окончание процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f0bc1eb1a788586e9e70dac7df350c5a9e71bce2f195e4dc5701262122237b85"},{"code_id":"APK_RF","article_number":"115","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, утрачивают право на совершение процессуальных действий с истечением процессуальных сроков, установленных настоящим Кодексом или иным федеральным законом либо арбитражным судом.\n\n2. Заявления, жалобы и другие поданные по истечении процессуальных сроков документы, если отсутствует ходатайство о восстановлении или продлении пропущенных сроков, не рассматриваются арбитражным судом и возвращаются лицам, которыми они были поданы.","article_title":"Статья 115. Последствия пропуска процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"46064efc9ff9c81a932bbee1675b96476b9d3e331688625be60de4b832f21b9c"},{"code_id":"APK_RF","article_number":"116","version_date":"2002-07-24","article_text":"1. Течение всех неистекших процессуальных сроков приостанавливается одновременно с приостановлением производства по делу.\n\n2. Со дня возобновления производства по делу течение процессуальных сроков продолжается.","article_title":"Статья 116. Приостановление процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93fad423fd8b1f6ce66d8921b8a66224dc9c70e0256a9a03ddfb618b1e983bfa"},{"code_id":"APK_RF","article_number":"117","version_date":"2002-07-24","article_text":"1. Процессуальный срок подлежит восстановлению по ходатайству лица, участвующего в деле, если иное не предусмотрено настоящим Кодексом.\n\nВосстановление пропущенного процессуального срока арбитражным судом указывается в соответствующем судебном акте.\n\nКопия определения направляется лицу, обратившемуся с ходатайством, не позднее следующего дня после дня вынесения определения.","article_title":"Статья 117. Восстановление процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9ddb14e1b0ae14ddf89f0572ea5c8b11cd273a390eba46592d41dc6950d1d52c"},{"code_id":"APK_RF","article_number":"118","version_date":"2002-07-24","article_text":"1. Назначенные арбитражным судом процессуальные сроки могут быть им продлены по заявлению лица, участвующего в деле, по правилам, предусмотренным статьей 117 настоящего Кодекса.\n\n2. Определение арбитражного суда об отказе в продлении назначенного им процессуального срока может быть обжаловано.","article_title":"Статья 118. Продление процессуальных сроков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5318030a6eec505cf5c96425d851f47ebb7b1931486b54ce5f2b300d166d9a67"},{"code_id":"APK_RF","article_number":"119","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 119. Наложение судебных штрафов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bcd71eed48f3dded8dab96cc5f46af72c3c3961669f6f84d71b16cf3be1bf94b"},{"code_id":"APK_RF","article_number":"12","version_date":"2002-07-24","article_text":"1. Судопроизводство в арбитражном суде ведется на русском языке - государственном языке Российской Федерации.\n\n2. Лицам, участвующим в деле и не владеющим русским языком, арбитражный суд разъясняет и обеспечивает право знакомиться с материалами дела, участвовать в судебных действиях, выступать в суде на родном языке или свободно выбранном языке общения и пользоваться услугами переводчика.","article_title":"Статья 12. Язык судопроизводства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7c7cd197793fb2e12bbc3510e81ce2ef27555286977902473bcc8f8422058467"},{"code_id":"APK_RF","article_number":"120","version_date":"2002-07-24","article_text":"1. Вопрос о наложении судебного штрафа на лицо, присутствующее в судебном заседании, разрешается в том же судебном заседании арбитражного суда.\n\n2. Вопрос о наложении судебного штрафа на лицо, не присутствующее в судебном заседании, разрешается в другом судебном заседании арбитражного суда.\n\n3. Лицо, в отношении которого рассматривается вопрос о наложении судебного штрафа, извещается о времени и месте судебного заседания с указанием оснований проведения судебного заседания. Неявка надлежащим образом извещенного лица не является препятствием к рассмотрению вопроса о наложении судебного штрафа.\n\n4. По результатам рассмотрения вопроса о наложении судебного штрафа арбитражный суд выносит определение.\n\nКопия определения о наложении судебного штрафа направляется лицу, на которое наложен штраф, в пятидневный срок со дня вынесения определения.\n\n5. Определение о наложении судебного штрафа приводится в исполнение немедленно в порядке, установленном для исполнения решения арбитражного суда.\n\nИсполнительный лист направляется арбитражным судом судебному приставу-исполнителю по месту жительства или адресу лица, на которое наложен судебный штраф. (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n6. Определение арбитражного суда о наложении судебного штрафа может быть обжаловано в десятидневный срок со дня получения лицом, на которое наложен судебный штраф, копии определения.\n\n7. Подача жалобы на определение о наложении судебного штрафа не приостанавливает исполнение определения.","article_title":"Статья 120. Порядок рассмотрения вопроса о наложении судебного штрафа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"351886b83fc62779064ff723f60a6d41e08cd9954cd1645eef51c88b1adeb854"},{"code_id":"APK_RF","article_number":"121","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, и иные участники арбитражного процесса извещаются арбитражным судом о принятии искового заявления или заявления к производству и возбуждении производства по делу, о времени и месте судебного заседания или совершения отдельного процессуального действия путем направления копии судебного акта в порядке, установленном настоящим Кодексом, не позднее чем за пятнадцать дней до начала судебного заседания или совершения отдельного процессуального действия, если иное не предусмотрено настоящим Кодексом.\n\nИнформация о принятии искового заявления или заявления к производству, о времени и месте судебного заседания или совершения отдельного процессуального действия размещается арбитражным судом в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" не позднее чем за пятнадцать дней до начала судебного заседания или совершения отдельного процессуального действия, если иное не предусмотрено настоящим Кодексом. Документы, подтверждающие размещение арбитражным судом в установленном порядке в информационно-телекоммуникационной сети \"Интернет\" указанных сведений, включая дату их размещения, приобщаются к материалам дела. (В редакции федеральных законов от 11.07.2011 № 200-ФЗ, от 30.12.2021 № 440-ФЗ)\n\n(Часть в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\n2. Судебный акт, которым извещаются или вызываются участники арбитражного процесса, должен содержать:\n\n1) наименование и адрес арбитражного суда, адрес официального сайта в информационно-телекоммуникационной сети \"Интернет\", на котором размещается информация о деятельности арбитражного суда, номера телефонов арбитражного суда, адреса электронной почты, по которым лица, участвующие в деле, могут получить информацию о рассматриваемом деле; (В редакции федеральных законов от 27.07.2010 № 228-ФЗ, от 11.07.2011 № 200-ФЗ, от 30.12.2021 № 440-ФЗ)\n\n2) время и место судебного заседания или проведения отдельного процессуального действия;\n\n3) наименование лица, извещаемого или вызываемого в суд;\n\n4) наименование дела, по которому осуществляется извещение или вызов, а также указание, в качестве кого лицо вызывается;\n\n5) указание, какие действия и к какому сроку извещаемое или вызываемое лицо вправе или обязано совершить.\n\n3. В случаях, не терпящих отлагательства, арбитражный суд может известить или вызвать лиц, участвующих в деле, и иных участников арбитражного процесса телефонограммой, телеграммой, по факсимильной связи или электронной почте либо с использованием иных средств связи.\n\nСудебные извещения, адресованные гражданам, в том числе индивидуальным предпринимателям, направляются по месту их жительства. При этом место жительства индивидуального предпринимателя определяется на основании выписки из единого государственного реестра индивидуальных предпринимателей.\n\nЕсли лицо, участвующее в деле, ведет дело через представителя, судебное извещение направляется также по месту нахождения представителя.\n\nЕсли лицо, участвующее в деле, заявило ходатайство о направлении судебных извещений по иному адресу, арбитражный суд направляет судебное извещение также по этому адресу. В этом случае судебное извещение считается врученным лицу, участвующему в деле, если оно доставлено по указанному таким лицом адресу.\n\nСудебное извещение в электронном виде направляется участнику арбитражного процесса посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. (Дополнение абзацем - Федеральный закон от 30.12.2021 № 440-ФЗ)\n\nСудебное извещение по спору в отношении зарегистрированного результата интеллектуальной деятельности или средства индивидуализации направляется также по адресу для переписки, указанному в соответствующем государственном реестре. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n(Часть в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\nЛица, участвующие в деле, несут риск наступления неблагоприятных последствий в результате непринятия мер по получению информации о движении дела, если суд располагает информацией о том, что указанные лица надлежащим образом извещены о начавшемся процессе, за исключением случаев, когда лицами, участвующими в деле, меры по получению информации не могли быть приняты в силу чрезвычайных и непредотвратимых обстоятельств. (В редакции Федерального закона от 31.12.2014 № 527-ФЗ)\n\n(Дополнение частью - Федеральный закон от 27.07.2010 № 228-ФЗ)","article_title":"Статья 121. Судебные извещения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9e5cf0fefa052d69baae17dcb6e73747105e26b20519d4de34ecf429f55423b9"},{"code_id":"APK_RF","article_number":"122","version_date":"2002-07-24","article_text":"1. Копия судебного акта направляется арбитражным судом по почте заказным письмом с уведомлением о вручении либо путем вручения адресату под расписку непосредственно в арбитражном суде или по месту нахождения адресата, а в случаях, не терпящих отлагательства, путем направления телефонограммы, телеграммы, по факсимильной связи или электронной почте либо с использованием иных средств связи.\n\nСудебный акт в электронном виде направляется участнику арбитражного процесса посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. Если арбитражный суд располагает доказательствами получения лицами, участвующими в деле, и иными участниками арбитражного процесса определения о принятии искового заявления или заявления к производству и возбуждении производства по делу, информации о времени и месте первого судебного заседания, судебные акты, которыми назначаются время и место последующих судебных заседаний или совершения отдельных процессуальных действий, направляются лицам, участвующим в деле, и иным участникам арбитражного процесса посредством размещения этих судебных актов в информационной системе, определенной Верховным Судом Российской Федерации, Судебным департаментом при Верховном Суде Российской Федерации, в разделе, доступ к которому предоставляется лицам, участвующим в деле, и иным участникам арбитражного процесса (далее также - в режиме ограниченного доступа). Арбитражный суд также вправе известить указанных лиц о последующих судебных заседаниях или совершении отдельных процессуальных действий по делу путем направления телефонограммы, телеграммы, по факсимильной связи или электронной почте либо с использованием иных средств связи. (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n(Часть в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\n2. В случае, если копия судебного акта вручается адресату или его представителю непосредственно в арбитражном суде либо по месту их нахождения, такое вручение осуществляется под расписку.","article_title":"Статья 122. Порядок направления арбитражным судом копий судебных актов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e157b3ff76a53b1394f2292e5d45bb2d87337f8a70f7d9aef7ce726b66e44589"}]$law7d0001$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
